describe('Login Page Error Handling', () => {
    beforeEach(() => {
        cy.visit('https://the-internet.herokuapp.com/login');
    });

    it('should display an error message for incorrect password', () => {
        cy.get('#username').type('tomsmith');
        cy.get('#password').type('wrongpassword');
        cy.get('button[type="submit"]').click();

        cy.url().should('eq', 'https://the-internet.herokuapp.com/login');
        cy.get('.flash.error').should('be.visible')
            .and('contain.text', 'Your password is invalid!');
    });

    it('should remain on the login page after failed login attempt', () => {
        cy.get('#username').type('tomsmith');
        cy.get('#password').type('wrongpassword');
        cy.get('button[type="submit"]').click();

        cy.url().should('eq', 'https://the-internet.herokuapp.com/login');
        cy.get('.flash.error').should('be.visible')
            .and('contain.text', 'Your password is invalid!');
    });
});
